// Um item por status: a API tem um endpoint e um par de filtros de data para cada um
const c = $('Config').first().json;
return ['lost', 'won'].map(s => ({ json: { status: s, de: s + 'From', ate: s + 'To', inicio: c.data_inicial, fim: c.data_final } }));

// Junta as páginas dos dois status numa lista só (sem repetir negócio+status)
const vistos = new Set(); const deals = [];
for (const i of $input.all()) {
  const b = i.json; const itens = Array.isArray(b.items) ? b.items : (Array.isArray(b.data) ? b.data : []);
  for (const d of itens) { const k = d.id + '|' + d.status; if (!vistos.has(k)) { vistos.add(k); deals.push(d); } }
}
return [{ json: { deals } }];

// Compara a API com o banco e monta as linhas que faltam, no formato do backfill de 05/11.
// Regras: docs/contrato-dados.md (unnichat_eventos, recuperação de 09/11).
const c = $('Config').first().json;
const deals = $('Juntar negócios').first().json.deals;
const ev = $input.all().map(i => i.json).filter(e => e && (e.negocio_id || e.proprietario));
const hoje = $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
const digitos = s => String(s ?? '').replace(/\D/g, '');
// mesma regra de cic_fone_chave: DDI + DDD + 8 últimos (10/11 dígitos ganham 55)
const chave = s => { let d = digitos(s); if (!d) return null; if (d.length === 10 || d.length === 11) d = '55' + d; return d.slice(0, 4) + d.slice(-8); };
const ja = new Set(ev.filter(e => e.negocio_id && (e.status === 'won' || e.status === 'lost')).map(e => e.negocio_id + '|' + e.status));
const porNeg = {}, porPessoa = {};
for (const e of ev) {
  const t = Date.parse(e.event_ts);
  if (e.negocio_id) (porNeg[e.negocio_id] = porNeg[e.negocio_id] || []).push({ ...e, t });
  if (e.pessoa_chave && e.proprietario) (porPessoa[e.pessoa_chave] = porPessoa[e.pessoa_chave] || []).push({ ...e, t });
}
const cf = (d, re) => { for (const f of (d.customFields || [])) { const nome = f.name ?? f.label ?? f.key ?? f.field?.name ?? ''; const v = f.value ?? f.text ?? f.data; if (re.test(String(nome)) && v !== null && v !== undefined && String(v).trim() !== '') return String(v).trim(); } return null; };
const linhas = []; const r = { api_lost: 0, api_won: 0, ja_existem: 0, inserir: 0, inserir_lost: 0, inserir_won: 0, com_proprietario: 0, prop_do_negocio: 0, prop_da_pessoa: 0, sem_telefone: 0, origem_customfield: 0, origem_negocio: 0, origem_padrao: 0, origem_vazia: 0, origem_normalizada: 0, copy_customfield: 0, copy_negocio: 0, por_dia: {} };
for (const d of deals) {
  if (d.status === 'lost') r.api_lost++; else if (d.status === 'won') r.api_won++; else continue;
  if (ja.has(d.id + '|' + d.status)) { r.ja_existem++; continue; }
  const tel = digitos(d.phoneNumber);
  if (!tel) { r.sem_telefone++; continue; }
  const ts = new Date(Math.floor(Date.parse(d.attributedIn) / 1000) * 1000);
  const t = ts.getTime();
  const doNeg = (porNeg[d.id] || []).filter(e => e.etapa_crm && e.proprietario && e.t <= t).sort((a, b) => b.t - a.t)[0];
  const pk = chave(tel);
  const daPessoa = doNeg ? null : (porPessoa[pk] || []).filter(e => e.t <= t).sort((a, b) => b.t - a.t)[0];
  const prop = doNeg ? doNeg.proprietario : (daPessoa ? daPessoa.proprietario : null);
  if (doNeg) r.prop_do_negocio++; else if (daPessoa) r.prop_da_pessoa++;
  if (prop) r.com_proprietario++;
  const ultNeg = (porNeg[d.id] || []).sort((a, b) => b.t - a.t);
  let origem = cf(d, /^origem$/i), fonteO = 'customfield';
  if (!origem) { const e = ultNeg.find(e => e.origem && String(e.origem).trim()); if (e) { origem = e.origem; fonteO = 'negocio'; } }
  const diaSp = DateTime.fromJSDate(ts).setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd');
  if (!origem && diaSp <= c.origem_padrao_ate) { origem = c.origem_padrao; fonteO = 'padrao'; }
  if (!origem) fonteO = 'vazia';
  // grafia errada no campo do negócio ('Disparo BF26') vira o nome do funil (decidido em 09/11)
  if (origem && /^disparo\s*bf26$/i.test(String(origem).trim())) { origem = c.origem_padrao; r.origem_normalizada++; }
  r['origem_' + fonteO]++;
  let copy = cf(d, /codigo[_ ]?copy/i);
  if (copy) r.copy_customfield++; else { const e = ultNeg.find(e => e.codigo_copy); if (e) { copy = e.codigo_copy; r.copy_negocio++; } }
  const email = d.email && String(d.email).trim() !== '' && String(d.email).trim() !== '-' ? String(d.email).trim() : null;
  const rs = d.reasonLoss ? (d.reasonLoss.description ?? d.reasonLoss) : null;
  linhas.push({
    event_ts: ts.toISOString(), telefone: tel, acao: 'Entrou na etapa', etapa_crm: null, status: d.status,
    motivo_perda: d.status === 'lost' ? rs : null, nome: d.contactName || d.name || null, email, origem: origem || null, codigo_copy: copy || null,
    conexao: c.conexao, pipeline: c.pipeline_nome, negocio_id: d.id, proprietario: prop,
    raw_payload: { backfill: 'api_deals_' + hoje, deal: { id: d.id, status: d.status, attributedIn: d.attributedIn, createdAt: d.createdAt, contactId: d.contactId, reasonLoss: rs } }
  });
  r.inserir++; r['inserir_' + d.status]++;
  const k = diaSp + ' ' + d.status; r.por_dia[k] = (r.por_dia[k] || 0) + 1;
}
return [{ json: { resumo: r, gravar: c.gravar === true, linhas } }];

// Lotes de 200 linhas por POST
const l = $input.first().json.linhas; const out = [];
for (let i = 0; i < l.length; i += 200) out.push({ json: { body: l.slice(i, i + 200) } });
return out;
